import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from "axios";

import Headerreg from "../components/Header_reg";

const BASE_URL = "http://localhost:3001/api/usuarios";
const Registro = () => {
  const [nom_1, setNom1] = useState("");
  const [ape_1, setApe1] = useState(""); // Nuevo: Primer Apellido
  const [id_usuario, setIdUsuario] = useState(""); // Nuevo: ID (Cédula/DNI)
  const [correo, setCorreo] = useState("");
  const [contrasena, setContrasena] = useState("");

  const [t_doc, setTDoc] = useState("1"); // Por defecto: 1 (: Cédula)
  const [telefono, setTelefono] = useState(""); 
  
  const [items, setItems] = useState([]); 

  const navigate = useNavigate();

  useEffect(() => {
    axios.get(`${BASE_URL}`)
      .then((response) => {
        setItems(response.data);
        console.log(response.data);
      })
      .catch(error => {
        console.error("Error al obtener los usuarios:", error)
      });
  }, []);

  const handleCreate = (e) => {
    e.preventDefault(); // Prevenir la recarga de la página

if (id_usuario.trim() && nom_1.trim() && ape_1.trim() && correo.trim() && telefono.trim() && contrasena.trim()) {      
      const userData = {
        // CAMPOS DEL FORMULARIO
        id_usuario: id_usuario.trim(), 
        nom_1: nom_1.trim(),
        ape_1: ape_1.trim(),
        correo: correo.trim(),
        telefono: telefono.trim(),
        contrasena: contrasena.trim(),
        t_doc: parseInt(t_doc), // Asegurar que sea un número

        // CAMPOS PREDETERMINADOS (Ajustar según tus reglas de negocio)
        nom_2: null, // Segundo nombre (opcional)
        ape_2: null, // Segundo apellido (opcional)
        codigo: null, 
        id_rol_usuario: 2, // 2 = Rol de Cliente/Usuario
  };

  axios.post(`${BASE_URL}/add`, userData)
        .then(response => {
          console.log("Registro Exitoso:", response.data);
          alert("¡Registro exitoso! Ya puedes iniciar sesión.");
          navigate('/login'); // Redirigir después del registro
        })
        .catch(error => {
          // Muestra el error específico de la respuesta del servidor
          const errorMessage = error.response?.data?.details || error.message;
          console.error("Error al registrar el usuario:", errorMessage);
          alert(`Error al registrar: ${errorMessage}`);
        });
    } else {
      alert("Por favor, complete todos los campos obligatorios.");
    } 
  };

  return (
    <>
      <Headerreg />
      
      <main>
        <form className="form-registro" onSubmit={handleCreate}>
          <h2 className="subtitulo">Crear cuenta</h2>

          <label htmlFor="nom_1">nombre</label>
          <input
            type="text"
            value={nom_1}
            onChange={(e) => setnom_1(e.target.value)}
            placeholder="Ingrese tu nombre"
          />

          <label htmlFor="correo">Correo electrónico</label>
          <input
            type="email"
            value={correo}
            onChange={(e) => setCorreo(e.target.value)}
            placeholder="Ingrese tu correo"
          />

          <label htmlFor="pessword">Contrasena</label>
          <input
            type="pessword"
            value={contrasena}
            onChange={(e) => setcontrasena(e.target.value)}
            placeholder="Ingresa tu contrasena"
          />

          <button onClick={handleCreate}>Registrarse</button>
        </form>
      </main>
        </>
    );
}

export default Registro;
